///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_Chk_form
 * @description Chk form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_Chk_form = async function () {
    const sbmOptions = {
        id: "tx_Chk_form",
        method: "post",
        action: "/stdcd/mfEtn.do?method=etnModifyProcess",
        ref: "dma_ChkFormReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name emailCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name checkRegData
 * @description check Reg Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkRegData = function () {
    const vl = dma_hiddenStore.get("regType");
    if (vl !== '') {
        // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
        const tObj = $('input[name=std_cd_apct_tp_cd][value="' + vl + '"]');
        if (tObj.length > 0) {
            // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
            $(tObj)[0].checked = true;
        }
    }
    const email = dma_hiddenStore.get("ipt_regEmail");
    if (email !== '') {
        const emails = email.split("@");
        if (emails.length > 0) {
            $c.util.getComponent('ipt_email01').setValue(emails[0]);
        }
        if (emails.length > 1) {
            $c.util.getComponent('ipt_email02').setValue(emails[1]);
        }
    }
    const tel = dma_hiddenStore.get("ipt_regTel");
    if (tel !== '') {
        const tels = tel.split("-");
        if (tels.length > 0) {
            $c.util.getComponent('ipt_ph01').setValue(tels[0]);
        }
        if (tels.length > 1) {
            $c.util.getComponent('ipt_ph02').setValue(tels[1]);
        }
        if (tels.length > 2) {
            $c.util.getComponent('ipt_ph03').setValue(tels[2]);
        }
    }
    const fax = dma_hiddenStore.get("ipt_regFax");
    if (fax !== '') {
        const faxs = fax.split("-");
        if (faxs.length > 0) {
            $c.util.getComponent('ipt_fax01').setValue(faxs[0]);
        }
        if (faxs.length > 1) {
            $c.util.getComponent('ipt_fax02').setValue(faxs[1]);
        }
        if (faxs.length > 2) {
            $c.util.getComponent('ipt_fax03').setValue(faxs[2]);
        }
    }
    const hpNo = $c.util.getComponent('ipt_encrypCellphoneNo').getValue();
    const hpNos = hpNo.split("-");
    if (hpNos.length > 0) {
        $c.util.getComponent('ipt_encrypCellphoneNo1').setValue(hpNos[0]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo2').setValue(hpNos[1]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo3').setValue(hpNos[2]);
    }
};

/**
 * @method
 * @name setComma
 * @description set Comma 처리
 * @returns {void}
 * @hidden N
 */
scwin.setComma = function () {
    $c.util.getComponent('ipt_isuAmt').setValue($c.num.formatNumber($c.util.getComponent('ipt_isuAmt').getValue()));
    // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
    $c.util.getComponent('txt_isuAmtMoney').setValue($c.num.formatNumberKor(String(((($('#ipt_isuAmt')[0]) && ($('#ipt_isuAmt')[0]).getValue) ? ($('#ipt_isuAmt')[0]).getValue() : (((($('#ipt_isuAmt')[0]) && typeof ($('#ipt_isuAmt')[0]).val === 'function') ? ($('#ipt_isuAmt')[0]).val() : ((($('#ipt_isuAmt')[0]) && ($('#ipt_isuAmt')[0]).value !== undefined) ? ($('#ipt_isuAmt')[0]).value : ($('#ipt_isuAmt')[0]))))) == null ? '' : ((($('#ipt_isuAmt')[0]) && ($('#ipt_isuAmt')[0]).getValue) ? ($('#ipt_isuAmt')[0]).getValue() : (((($('#ipt_isuAmt')[0]) && typeof ($('#ipt_isuAmt')[0]).val === 'function') ? ($('#ipt_isuAmt')[0]).val() : ((($('#ipt_isuAmt')[0]) && ($('#ipt_isuAmt')[0]).value !== undefined) ? ($('#ipt_isuAmt')[0]).value : ($('#ipt_isuAmt')[0])))))).replace(/,/g, '')));
};

/**
 * @method
 * @name setCfi
 * @description set Cfi 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCfi = function () {
    const map_cfi_cd = $c.util.getComponent('ipt_cfiCd').getValue();
    const substr_cfi_category = map_cfi_cd.substring(0, 1);
    const substr_cfi_group = map_cfi_cd.substring(1, 2);
    const substr_cfi_attr1 = map_cfi_cd.substring(2, 3);
    const substr_cfi_attr2 = map_cfi_cd.substring(3, 4);
    const substr_cfi_attr3 = map_cfi_cd.substring(4, 5);
    const substr_cfi_attr4 = map_cfi_cd.substring(5, 6);
    $c.util.getComponent('ipt_cfiCdCategory').setValue(substr_cfi_category);
    // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
    $('input[name=group][value="' + substr_cfi_group + '"]').attr("checked", true);
    // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
    scwin.chg_group($("#group_" + substr_cfi_group));
    $c.util.getComponent('slc_attr01').setValue(substr_cfi_attr1);
    $c.util.getComponent('slc_attr02').setValue(substr_cfi_attr2);
    $c.util.getComponent('slc_attr03').setValue(substr_cfi_attr3);
    $c.util.getComponent('slc_attr04').setValue(substr_cfi_attr4);
    scwin.chg_attr();
};

